"use strict";(self.webpackChunkreact_portfolio=self.webpackChunkreact_portfolio||[]).push([[4706],{4706:function(i){i.exports=JSON.parse('{"name":"Patrick Goodwin","menu":{"home":"Dom","about":"O meni","portfolio":"Portfelj","projects":"Projekti web stranice","tiger":"Jezik tigra","portfolio_translator":"Prevoditelj portfelja","formatter":"Formater JSON & YAML","contact":"Kontaktirajte me"},"home":{"title":"Senior Full-Stack in\u017eenjer | Proizvod i sustavi","animated":{"first":"Senior Full-Stack in\u017eenjer","second":"Graditelj sustava i arhitekture","third":"SaaS proizvodni in\u017eenjer","fourth":"Pouzdan softver, poslovni rezultati"},"footer":"Web stranica je sada prevedena i dostupna na vi\u0161e od 100 jezika!","descriptionA":"Vi\u0161i in\u017eenjer s vi\u0161e od 6 godina iskustva u prevo\u0111enju proizvoda od dvosmislenih zahtjeva do pouzdanih proizvodnih sustava. Dizajniram arhitekturu iza aplikacija React, Angular, .NET, Node.js, Java, C#, Go i SQL: jasne granice usluga, trajni modeli podataka, obrasci sigurnog pristupa i putovi isporuke timovi mogu raditi s povjerenjem.","descriptionB":"Moj rad povezuje in\u017eenjerske odluke s poslovnim rezultatima. Od SaaS-a za procjenu konstrukcije koji podatke prora\u010dunske tablice pretvara u prijedloge spremne za klijenta do web platformi za stvaranje prihoda, izra\u0111ujem softver oko tijeka rada, rizika i mjerljivu vrijednost koja je va\u017ena ljudima koji je koriste.","portfolio_button":"Moj portfelj","contact_button":"Kontaktirajte me","about_button":"O meni"},"about":{"title":"O meni","personal_summary":{"title":"Osobni sa\u017eetak","text":"Ja sam stariji in\u017eenjer sa sjedi\u0161tem u Orlandu, FL, koji posjeduje put od problema proizvoda do ishoda proizvodnje. Odabirem tehnologije u slu\u017ebi sustava: .NET i Entity Framework Core kada su jako strukturirana domena i postojanost koja se mo\u017ee testirati va\u017eni; Angular ili React kada je slo\u017een tijek rada treba su\u010delje koje se mo\u017ee odr\u017eavati; Node.js ili Go kada API, integracija ili alat visokih performansi trebaju fokusirano vrijeme izvo\u0111enja. U SaaS proizvodima, internim tijekovima rada i platformama usmjerenim na kupce, vodim s izri\u010ditim kompromisima, sigurnim i otpornim dizajnom, automatiziranim testiranjem i praksama isporuke koje pomozite timovima da isporu\u010de vrijedan softver bez ostavljanja operativnih dugova."},"professional_experience":{"title":"Profesionalno iskustvo","entries":[{"jobtitle":"Vi\u0161i softverski in\u017eenjer","where":"Interaktivni dizajn","date":"2025. - danas"},{"jobtitle":"softverski in\u017eenjer","where":"Orion180 osiguranje","date":"2024 - 2025 (prikaz, stru\u010dni)."},{"jobtitle":"softverski in\u017eenjer","where":"SupremeMC","date":"2020 - 2024"},{"jobtitle":"softverski in\u017eenjer","where":"Ubrzajte u\u010denje","date":"2023"},{"jobtitle":"Vode\u0107i softverski in\u017eenjer (studentski program)","where":"GDI program Sveu\u010dili\u0161ta Clemson","date":"2021 - 2022"},{"jobtitle":"Nadzornik stola","where":"Sveu\u010dili\u0161te Clemson","date":"2021 - 2022"}]},"technical_skills":{"title":"Tehni\u010dke vje\u0161tine","header1":"Programski jezici","header2":"Okviri i biblioteke","header3":"Alati i tehnologije"},"services":{"title":"Moje usluge","entries":[{"title":"Full Stack in\u017eenjering","text":"Vodim isporuku proizvoda od po\u010detka do kraja: prevo\u0111enje poslovnih tijekova rada u granice sustava, podatkovne modele, API-je i su\u010delja, zatim obavljanje posla kroz testiranje, implementaciju, i ponavljanje. Cilj je softver koji tim mo\u017ee razviti i kojim mo\u017ee upravljati, a ne zbirka nepovezanih zaslona."},{"title":"Arhitektura proizvoda i platforme","text":"Biram platforme i uzorke na temelju problema: slojevite .NET usluge za poslovne domene, Angular ili React aplikacije vo\u0111ene komponentama za slo\u017eene operacije, relacijske podatkovni modeli za odgovorne tijekove rada i integracije dizajnirane imaju\u0107i na umu na\u010dine kvarova, kontrolu pristupa i mogu\u0107nost odr\u017eavanja."},{"title":"Isporuka spremna za proizvodnju","text":"Gradim s obzirom na realnost nakon pokretanja: tajne koje se dr\u017ee izvan kontrole izvora, eksplicitne staze migracije baze podataka, autorizacija temeljena na ulogama, provjera valjanosti na granicama sustava, automatizirani testovi, svijest o CI/CD-u i prakti\u010dna promatranost. To su detalji koji pretvaraju prototip u pouzdan softver."}]}},"portfolio":{"title":"Portfelj","filter_by":"Filtriraj portfelj prema:","entries":{"biblioteca":{"title":"Biblioteka JSON","text":"Cjevovod lokalizacije temeljen na Pythonu koji pretvara jedan strukturirani izvor sadr\u017eaja u globalno dostupan portfelj. Obra\u0111uje podatke o prijevodu kao sustav koji se mo\u017ee odr\u017eavati, a ne ru\u010dno umno\u017eenu kopiju stranice, omogu\u0107uju\u0107i web-lokaciji skaliranje na 100+ jezika i \u010dine\u0107i globalni doseg operativna sposobnost umjesto jednokratne zna\u010dajke.","link":"https://github.com/pattygcoding/Biblioteca-JSON"},"connect_four":{"title":"Spoji \u010detiri","text":"Ogromna obitelj od preko 50+ implementacija igre Connect Four. Ovaj projekt uklju\u010duje implementacije u vi\u0161e od 30 razli\u010ditih programskih jezika, uklju\u010duju\u0107i Javu, C++, Python, JavaScript itd. Osim toga, tako\u0111er uklju\u010duje vi\u0161e od 20 razli\u010ditih okvira ili drugih formata, uklju\u010duju\u0107i React.js, Ruby on Rails, ASP.NET i jo\u0161 mnogo toga.","link":"https://github.com/pattygcoding/Connect-Four-Language-Tree"},"grocery_app":{"title":"Aplikacija za trgovinu namirnicama","text":"Puna aplikacija .NET 9 Blazor Server koja demonstrira namjernu pozadinsku arhitekturu za poslovni tijek rada. Podjela kontrolera/usluge/spremi\u0161ta omogu\u0107uje neovisno testiranje pravila aplikacije, pristupa podacima i prezentacije; Entity Framework Core pru\u017ea trajnu postojanost; i sveobuhvatan paket testova \u0161titi pona\u0161anje kako se proizvod razvija.","link":"https://github.com/pattygcoding/Grocery-App-Blazor"},"interop":{"title":"Interop projekt","text":"Referenca me\u0111ujezi\u010dne interoperabilnosti koja obuhva\u0107a 15 programskih jezika i 18 obrazaca izvr\u0161avanja. Projekt istra\u017euje granice na kojima sustavi \u010desto postaju krhki: procesni ugovori, razmjena podataka, pona\u0161anje u vremenu izvo\u0111enja i ponovljivi putevi integracije. Odra\u017eava sustavno razmi\u0161ljanje koje je potrebno kada je proizvod ve\u0107i od jedne hrpe.","link":"https://github.com/pattygcoding/Interop-Samples"},"inventory_register":{"title":"Registar inventara","text":"Puni POS i radni tijek inventara izgra\u0111en uz Angular 17+ i Node.js. Modelira operativne probleme B2B sustava: autentificirane korisnike, kontrolu pristupa temeljenu na ulogama, to\u010dnost inventara i la\u017eni tijek pla\u0107anja. Projekt je osmi\u0161ljen oko stvarnog posla koji obavlja tim registra, a ne samo oko kataloga zna\u010dajki okvira.","link":"https://github.com/pattygcoding/Restaurant-Inventory-Register"},"formatter":{"title":"JSON & YAML Auto Formatter","text":"Alat za JSON i YAML provjeru valjanosti i formatiranje temeljen na pregledniku ugra\u0111en u Go i kompiliran u WebAssembly. Premje\u0161tanje mehanizma za ra\u0161\u010dlanjivanje u WASM odr\u017eava interakciju osjetljivom i lokalnom u odnosu na preglednik dok se primjenjuje pravi ra\u0161\u010dlanjiva\u010d za hvatanje neva\u017ee\u0107ih unosa. To je fokusirani primjer odabira izvedbene arhitekture za performanse, prenosivost i povjerenje korisnika.","link":"https://github.com/pattygcoding/JSON-YAML-Auto-Formatter"},"takeoff_engine":{"title":"Motor za polijetanje","text":"Konstrukcija koja procjenjuje SaaS izgra\u0111ena oko skupog tijeka rada izvo\u0111a\u010da sklonog pogre\u0161kama. Proizvod React + Express unosi CSV i Excel podatke, mapira nedosljedne stupce u upotrebljivi model domene, izra\u010dunava iskop rovova i koli\u010dine zemljanih radova, prati rad i markup i proizvodi PDF i Word prijedloge spremne za klijenta. Ovo je in\u017eenjering cijelog \u017eivotnog ciklusa proizvoda: ra\u0161\u010dlanjivanje podataka, pravila izra\u010duna, ugla\u0111eni radni tijek operatera i isporu\u010deni rezultati koji poma\u017eu poduze\u0107u prije\u0107i s sirovih unosa na ponudu.","link":"https://github.com/pattygcoding/takeoff-engine"},"minecraft_json_generator":{"title":"Minecraft JSON generator","text":"Lagani JSON generator ugra\u0111en u Python za Minecraft resurse i pakete podataka. Ovaj se projekt koristi za generiranje JSON datoteka za Minecraft modifikacije, uklju\u010duju\u0107i prilago\u0111ene stavke, blokove i entitete. Vrlo korisno ne samo za stvaranje prilago\u0111enih paketa podataka, ve\u0107 i za modove putem zna\u010dajke promjene naziva moda.","link":"https://github.com/pattygcoding/Minecraft-JSON-Generator"},"educational_experience":{"title":"Moje obrazovno iskustvo","text":"Uz svoje osobne projekte, stekao sam i brojne vje\u0161tine iz obrazovnog iskustva. Kliknite ovdje da pogledate moj LinkedIn profil za vi\u0161e informacija.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"professional_experience":{"title":"Moje profesionalno iskustvo","text":"\u0160est i vi\u0161e godina profesionalnog in\u017eenjerskog iskustva u timovima proizvoda, poslovnim platformama i softveru usmjerenom na korisnike. Moj posao je uklju\u010divao izgradnju aplikacijskih slojeva koji se mogu odr\u017eavati, suradnju u razli\u010ditim disciplinama isporuke i dono\u0161enje tehni\u010dkih odluka sa \u017eivotnim ciklusom proizvoda, operativnim rizik i dugoro\u010dno vlasni\u0161tvo u vidu.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"portfolio_website":{"title":"Web stranica portfelja Patricka Goodwina","text":"Proizvodno usmjeren React portfelj koji pristupa\u010dnost i globalni doseg tretira kao in\u017eenjerske zahtjeve. Uklju\u010duje cjevovod za prevo\u0111enje koji se mo\u017ee odr\u017eavati za vi\u0161e od 100 jezika, interaktivne alate podr\u017eane WebAssemblyjem, responzivne i pristupa\u010dne obrasce korisni\u010dkog su\u010delja i arhitekturu projekta dizajniran da raste kako se isporu\u010duju novi radovi.","link":"https://www.pattygcoding.com"},"lua_library":{"title":"Patrick\'s Lua Script Library","text":"Korisna biblioteka Lua skripti za budu\u0107e potrebe. Ova se biblioteka koristi za automatizaciju zadataka u Lua skriptama, \u0161to mo\u017ee biti korisno za zadatke koji zahtijevaju performanse, budu\u0107i da je Lua obi\u010dno br\u017ei skriptni jezik od Pythona i Rubyja.","link":"https://github.com/pattygcoding/Lua-Scripts"},"excel_scripts":{"title":"Patrick\'s Microsoft Excel Spreadsheet Scripts (VBA)","text":"Korisna biblioteka VBA skripti za Microsoft Excel. Ova se biblioteka koristi za automatizaciju zadataka u Excel prora\u010dunskim tablicama.","link":"https://github.com/pattygcoding/Spreadsheet-Scripts"},"neovim_config":{"title":"Patrick\'s Neovim Config","text":"Moja osobna Neovim konfiguracija. Ovaj se projekt koristi za konfiguriranje Neovim-a po mom ukusu, uklju\u010duju\u0107i prilago\u0111ena povezivanja tipki, teme i dodatke. Ovaj projekt se koristi kako bi Neovim bio lak\u0161i za kori\u0161tenje i u\u010dinkovitiji za moju osobnu upotrebu.","link":"https://github.com/pattygcoding/Neovim-Config"},"python_maps":{"title":"Patrickov generator karata","text":"Python geoprostorni alat za izvje\u0161\u0107ivanje izra\u0111en s GeoPandas i Matplotlib za generiranje karata okruga i dr\u017eava SAD-a. Pretvara geografske podatke u \u010ditljive artefakte analize, demonstriraju\u0107i na\u010din razmi\u0161ljanja o prijenosu podataka: odaberite prave biblioteke domene, normalizirajte ulaze i proizvedite izlaze koji podr\u017eati jasne odluke.","link":"https://i.imgur.com/HxYLSXC.png"},"powershell_library":{"title":"Patrick\'s PowerShell Script Library","text":"Korisna biblioteka PowerShell skripti za budu\u0107e potrebe. Korisno sa zna\u010dajkom skripte $profile, smatram da je ovo neizmjerno korisno za automatiziranje zadataka s Windows terminala, jer sam \u010dest korisnik Windows OS-a.","link":"https://github.com/pattygcoding/Powershell-Scripts"},"ruby_library":{"title":"Patrick\'s Ruby Script Library","text":"Korisna biblioteka Ruby skripti za budu\u0107e potrebe. Korisno za budu\u0107e razvojne koncepte Ruby on Rails.","link":"https://github.com/pattygcoding/Ruby-Scripts"},"pdf_builder":{"title":"PDF Skills Builder","text":"Tijek rada za generiranje dokumenata izgra\u0111en s Python, Pdfkit, Jinja2, HTML i strukturiranim JSON podacima. Odvaja podatke za vi\u0161ekratnu upotrebu od prezentacijskih predlo\u017eaka kako bi se dosljedno generirali prilago\u0111eni PDF \u017eivotopisi, prakti\u010dan obrazac za smanjenje ru\u010dnog rada i izradu poslovnih dokumenata ponovljiv.","link":"https://github.com/pattygcoding/PDFBuilderPublic"},"rijandel_encryption":{"title":"Projekt \u0161ifriranja Rijandel","text":"Usporedni skup od 10+ Rijndael implementacija u 128-, 192- i 256-bitnim varijantama. Ponovna implementacija algoritma osjetljivog na sigurnost na razli\u010ditim jezicima disciplinirana je vje\u017eba to\u010dnih specifikacija, pona\u0161anja koje se mo\u017ee testirati i ograni\u010denja prenosivosti na razini jezika, svi korisni instinkti za sustave koji rukuju osjetljivim podacima.","link":"https://github.com/pattygcoding/SupremeMC"},"suprememc":{"title":"SupremeMC Minecraft Mod","text":"Minecraft Mod koji igrici dodaje prilago\u0111ene alate, oklope, rulje, blokove, dimenzije i mnoge druge zna\u010dajke. Izgra\u0111en s Java verzijama 8-17 za odabrane Minecraft verzije izme\u0111u 1.16 i 1.20.","link":"https://www.curseforge.com/minecraft/mc-mods/suprememc"},"tiger_programming_language":{"title":"Tiger programski jezik","text":"Prilago\u0111eni programski jezik i tuma\u010d ugra\u0111en u Go za istra\u017eivanje dizajna vremena izvo\u0111enja jezika, pona\u0161anja pri izvr\u0161avanju i kompromisa u izvedbi. Kompajliranjem u WebAssembly i integriranjem u portfelj stvara se stvarna povr\u0161ina proizvoda koja se mo\u017ee pregledati za in\u017eenjering na razini sustava umjesto da se posao ostavi kao eksperiment samo za spremi\u0161te.","link":"https://www.pattygcoding.com/tiger"},"tiger_tailgating_pros":{"title":"Web stranica za profesionalce Tiger Tailgatinga","text":"Web stranica React isporu\u010dena za tvrtku koja se bavi prodajom robe u Clemsonu, SC. Rad prevodi ponudu male tvrtke u jasno putovanje korisnika i pouzdanu prisutnost na webu, primjenjuju\u0107i razmi\u0161ljanje o proizvodu kako bi se pomoglo stvarnoj organizaciji da pretvori interes u upite i prihode.","link":"https://github.com/pattygcoding/TTProsBeta"},"turing_machine":{"title":"Projekt Turingovog stroja","text":"Obitelj od preko 30+ implementacija Turingovog stroja. Koristi se za demonstraciju turing potpunosti za razli\u010dite programske jezike za istra\u017eivanje, posebno za programski jezik Tiger.","link":"https://github.com/pattygcoding/Turing-Machines"}}},"tiger_programming_language":{"title":"Tiger programski jezik"},"contact":{"title":"Kontaktirajte me","header":"Podaci za kontakt","email":"pattygsocials@gmail.com","description":"Odgovaram na upite putem e-po\u0161te i LinkedIn poruka. Tako\u0111er \u0107u uzvratiti poziv ako moj broj bude naveden u \u017eivotopisu ili na neki drugi na\u010din, iako radije dr\u017eim svoj telefonski broj privatnim."},"formatter":{"title":"JSON & YAML Linter","description":"Alat za kvalitetu podataka temeljen na pregledniku koji provjerava i formatira JSON i YAML pomo\u0107u Go motora kompiliranog na WebAssembly. Arhitektura odr\u017eava ra\u0161\u010dlanjivanje blizu korisnika za brzu, privatnu povratnu informaciju dok provodi pravila stvarne sintakse na granici podataka. To je kompaktan primjer dizajniranja pouzdanog tijeka rada programera oko ispravnosti, performansi i povjerenja.","more_info1":"Za vi\u0161e informacija pogledajte README u","more_info2":"Repozitorij JSON/YAML Formatter.","format_as":"Oblikuj kao:","auto_detect":"Automatsko otkrivanje","format":"Lint & Format","valid_json":"\u2713 Valjani JSON","valid_yaml":"\u2713 Va\u017ee\u0107i YAML","invalid_json":"Neva\u017ee\u0107i JSON","invalid_yaml":"Neva\u017ee\u0107i YAML","empty_input":"Unesite JSON ili YAML za lint.","too_large":"Unos je prevelik (dopu\u0161teno najvi\u0161e 1 MB).","fixed_yaml_spacing":"\u26a0 YAML je imao neva\u017ee\u0107i razmak/uvlaku, ali je automatski popravljen i formatiran.","loading":"U\u010ditavanje formatera...","waiting_for_input":"\u010ceka se unos...","load_failed":"Nije mogu\u0107e u\u010ditati formater.","output":"Izlaz:","input_code":"Ulazni","json_examples":"JSON primjeri","yaml_examples":"YAML primjeri"},"tiger":{"title":"Jezik tigra","description":"Tiger je prilago\u0111eni programski jezik i Go interpreter napravljen za istra\u017eivanje arhitekture vremena izvo\u0111enja, semantike jezika i kompromisa u izvedbi. Kompajliranje tuma\u010da u WebAssembly pretvara rad sustava u interaktivni proizvod temeljen na pregledniku: korisnici mogu izravno izvr\u0161avati programe dok vrijeme izvo\u0111enja ostaje prenosivo i izolirani od glavne aplikacije.","more_info1":"Za vi\u0161e informacija pogledajte README u","more_info2":"Tiger programski jezik GitHub Repozitorij.","select_engine":"Odaberite motor:","tiger_code":"Kod tigra:","run_tiger":"Tr\u010di Tiger","output":"Izlaz:"},"tab":{"title":"Patrick Goodwin","description":"Vi\u0161i full-stack in\u017eenjer sa 6+ godina iskustva u dizajniranju SaaS proizvoda, proizvodnih sustava i softvera za stvaranje prihoda."},"copy":{"text":"Kopirati","copied":"Kopirano!"},"social_media":{"github":"GitHub","linkedin":"LinkedIn","youtube":"YouTube","text_strip":"slijedi me"},"languages":{"title":"Prevoditelj portfelja","description":"Otkrijte kako je moj portfelj dostupan posjetiteljima iz cijelog svijeta uz podr\u0161ku za vi\u0161e od 100 jezika.","global_accessibility":{"title":"Globalna pristupa\u010dnost","description":"Moj je portfelj dostupan na vi\u0161e od {count} jezika, \u0161to ga \u010dini dostupnim posjetiteljima iz cijelog svijeta. Ovaj vi\u0161ejezi\u010dni pristup pokazuje moju predanost inkluzivnosti i globalnom dosegu u razvoju softvera.","stats":{"languages_supported":"Podr\u017eani jezici","countries_represented":"Zastupljene zemlje","continents_covered":"Pokriveni kontinenti"}},"features":{"title":"Zna\u010dajke","items":[{"title":"Prijevod u stvarnom vremenu:","description":"Trenuta\u010dno mijenjajte jezike pomo\u0107u bira\u010da jezika"},{"title":"Jezik temeljen na URL-u:","description":"Postavke jezika sa\u010duvane su u URL-u"},{"title":"Podr\u0161ka za izvornu skriptu:","description":"Pravilno prikazivanje pisama kao \u0161to su arapski, kineski, hindski itd"},{"title":"Kulturolo\u0161ka osjetljivost:","description":"Prijevodi uzimaju u obzir kulturni kontekst, a ne samo doslovna zna\u010denja"},{"title":"SEO optimizirano:","description":"Svaka je jezi\u010dna varijanta optimizirana za tra\u017eilice"}]},"world_map":{"title":"Interaktivna karta svijeta","description":"Zadr\u017eite pokaziva\u010d iznad zemalja na karti da biste vidjeli njihove podr\u017eane jezike:","languages_label":"jezici","legend":{"supported":"Podr\u017eani jezici","not_supported":"Nema jezi\u010dne podr\u0161ke"},"zoom_controls":{"zoom_in":"Pove\u0107aj","zoom_out":"Smanji","reset":"Resetiraj prikaz"}},"supported_languages":{"title":"Podr\u017eani jezici"},"interactive_country_map":{"title":"Interaktivna karta zemlje","description":"Zadr\u017eite pokaziva\u010d mi\u0161a iznad zemalja u nastavku kako biste vidjeli njihove podr\u017eane jezike:","language_count":{"single":"jezik","multiple":"jezika"}},"tooltips":{"no_language_support":"Nema jezi\u010dne podr\u0161ke"}},"logotext":"PATRICK"}')}}]);